import'./cloud-sync.js';import{FRACTIONOPS_TRACKS,FRACTIONOPS_CHAIN,FRACTIONOPS_DIAGNOSTIC,recommendFractionOpsTrack,createBlankFractionOpsLearner}from'./fractionops-data.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],key='mathlab-fractionops-v1';
function blank(){return{a:createBlankFractionOpsLearner(),b:createBlankFractionOpsLearner(),learner:'a'}}function read(){try{return JSON.parse(localStorage.getItem(key))||blank()}catch{return blank()}}
let store=read(),learner=store.learner||'a',state=store[learner]||createBlankFractionOpsLearner(),attempts=0,hints=0,sessionId=null,completing=false;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function ensure(){const b=createBlankFractionOpsLearner();state={...b,...state,diagnostic:{...b.diagnostic,...state.diagnostic},missions:{...state.missions},sessions:{...state.sessions},evidence:{...b.evidence,...state.evidence},family:{...b.family,...state.family}}}function save(){state.updatedAt=new Date().toISOString();store={...read(),[learner]:state,learner};localStorage.setItem(key,JSON.stringify(store));$('#saveStatus').textContent='Saved offline · cloud sync follows parent sign-in'}function track(){return FRACTIONOPS_TRACKS[state.track||'explorer']}function done(i){return!!state.missions[FRACTIONOPS_CHAIN.missions[i].id]?.complete}function unlocked(i){return i===0||done(i-1)}function feedback(t,c=''){$('#feedback').textContent=t;$('#feedback').className='feedback '+c}
function load(id){sessionId=id;const x=state.sessions[id]||{attempts:0,hints:0,stage:0};attempts=x.attempts||0;hints=x.hints||0;return x}function session(stage){state.sessions[sessionId]={attempts,hints,stage};save()}function mark(k,ok){if(ok)state.evidence[k]='independent';else if(state.evidence[k]==='unknown')state.evidence[k]='learning'}function complete(i,dims=[],pending=false,preview=false){if(completing)return;completing=true;const m=FRACTIONOPS_CHAIN.missions[i],ind=attempts===0&&hints===0&&!preview;state.missions[m.id]={complete:!preview,preview,attempts,hints,track:state.track,completedAt:new Date().toISOString()};dims.forEach(x=>mark(x,ind));if(pending)state.retestDue=Date.now()+20*60*60*1000;if(!preview&&i<4)state.activeMission=i+1;if(sessionId)delete state.sessions[sessionId];sessionId=null;attempts=hints=0;save();setTimeout(render,350)}function tried(ok){if(!ok)attempts++;session(state.sessions[sessionId]?.stage||0)}function hint(t){return hints?`<div class="hint-box">${esc(t)}</div>`:''}function controls(){return'<div class="answer-row"><button class="secondary" data-action="hint">Give me one hint</button></div>'}function options(items,right,pos,attr){const a=items.map((x,i)=>({x,ok:i===right})),r=a.splice(right,1)[0];a.splice(pos,0,r);return a.map(o=>`<button class="choice" data-${attr}="${o.ok?'correct':'wrong'}">${esc(o.x)}</button>`).join('')}
function strip(f,label){const[n,d]=f.split('/').map(Number);return`<div class="fraction-model"><strong>${esc(label)} · ${esc(f)}</strong><div class="fraction-strip" style="--parts:${d}" aria-label="${n} of ${d} equal parts shaded">${Array.from({length:d},(_,i)=>`<i class="${i<n?'filled':''}"></i>`).join('')}</div></div>`}
function renderDiagnostic(){const d=state.diagnostic;if(d.index===3){state.track=state.track||recommendFractionOpsTrack(d.score);const t=track();$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${t.label}</h3><p>${t.description}</p><button class="primary" data-action="start">Build a shared unit →</button></div>`;return}const q=FRACTIONOPS_DIAGNOSTIC[d.index];$('#activity').innerHTML=`<p class="eyebrow">QUESTION ${d.index+1} OF 3</p><h3>${q.prompt}</h3><div class="answer-grid">${q.choices.map(x=>`<button class="choice" data-diag="${esc(x)}">${esc(x)}</button>`).join('')}</div><p class="microcopy">No timer. Ask what one piece means before calculating.</p>`;$$('[data-diag]').forEach(b=>b.onclick=()=>{if(b.disabled)return;$$('[data-diag]').forEach(x=>x.disabled=true);const ok=b.dataset.diag===q.answer;d.answers.push({id:q.id,correct:ok});if(ok)d.score++;d.index++;if(d.index===3)state.track=state.track||recommendFractionOpsTrack(d.score);feedback(ok?'Yes. The fraction unit stays meaningful.':q.why,ok?'good':'try');save();setTimeout(render,450)})}
function renderUnits(){const t=track(),p=t.build,x=state.sessions[sessionId]||{stage:0};if(!x.stage){$('#activity').innerHTML=`<p class="eyebrow">NAME THE PART SIZE FIRST</p><h3>How should we prepare ${p.a} ${p.op} ${p.b}?</h3><div class="fraction-models">${strip(p.a,'First amount')}${strip(p.b,'Second amount')}</div><div class="answer-grid">${options([p.unitRule,...p.wrongRules],0,t.pos,'unit')}</div>${controls()}${hint('The denominator names the size of one part. Counts can combine only when those part sizes match.')}`;$$('[data-unit]').forEach(b=>b.onclick=()=>{const ok=b.dataset.unit==='correct';tried(ok);if(ok){session(1);renderMission()}else feedback('Compare the size named by each denominator before touching the numerators.','try')});return}if(x.stage===1){$('#activity').innerHTML=`<p class="eyebrow">COUNT ONE KIND OF PIECE</p><h3>Which work keeps every fraction unit honest?</h3><div class="answer-grid">${options([p.work,...p.wrongWork],0,(t.pos+1)%3,'unitwork')}</div>${controls()}${hint('Equivalent fractions rename an amount; they do not change how much it is.')}`;$$('[data-unitwork]').forEach(b=>b.onclick=()=>{const ok=b.dataset.unitwork==='correct';tried(ok);if(ok){session(2);renderMission()}else feedback('Every term in the calculation must count the same-sized parts.','try')});return}$('#activity').innerHTML=`<p class="eyebrow">NAME THE RESULT</p><div class="strategy-card"><strong>${p.work}</strong></div><h3>What is ${p.a} ${p.op} ${p.b}?</h3><div class="answer-grid">${options([p.answer,...p.wrongAnswers],0,(t.pos+2)%3,'unitanswer')}</div>${controls()}${hint('Read the final count and keep the common fraction unit.')}`;$$('[data-unitanswer]').forEach(b=>b.onclick=()=>{const ok=b.dataset.unitanswer==='correct';tried(ok);if(ok){const dims=['units','calculation','explanation'];if(t.id!=='explorer')dims.push('equivalence');feedback('Correct. Same-sized parts made the calculation meaningful.','good');complete(1,dims)}else feedback('Match the answer to the shared-unit work.','try')})}
function renderStory(){const t=track(),p=t.solve,x=state.sessions[sessionId]||{stage:0};if(!x.stage){$('#activity').innerHTML=`<p class="eyebrow">UNDERSTAND THE STORY</p><h3>${p.story}</h3><p class="prompt">Which plan preserves the meaning of the quantities?</p><div class="answer-grid">${options([p.plan,...p.wrongPlans],0,(t.pos+1)%3,'plan')}</div>${controls()}${hint('Decide whether the story joins or separates amounts, then choose a unit both fractions can use.')}`;$$('[data-plan]').forEach(b=>b.onclick=()=>{const ok=b.dataset.plan==='correct';tried(ok);if(ok){session(1);renderMission()}else feedback('Connect the operation to what changes in the story.','try')});return}if(x.stage===1){$('#activity').innerHTML=`<p class="eyebrow">CALCULATE WITH COMMON UNITS</p><h3>Which work follows the plan?</h3><div class="answer-grid">${options([p.work,...p.wrongWork],0,t.pos,'storywork')}</div>${controls()}${hint('Rename without changing value, then combine or separate the numerators.')}`;$$('[data-storywork]').forEach(b=>b.onclick=()=>{const ok=b.dataset.storywork==='correct';tried(ok);if(ok){session(2);renderMission()}else feedback('Check each equivalent fraction before calculating.','try')});return}$('#activity').innerHTML=`<p class="eyebrow">RETURN TO THE STORY</p><div class="strategy-card"><strong>${p.work}</strong></div><h3>Which answer includes the correct amount and unit?</h3><div class="answer-grid">${options([p.answer,...p.wrongAnswers],0,(t.pos+2)%3,'storyanswer')}</div>${controls()}${hint('The number and the story unit must both match the calculation.')}`;$$('[data-storyanswer]').forEach(b=>b.onclick=()=>{const ok=b.dataset.storyanswer==='correct';tried(ok);if(ok){feedback('Yes. The number, operation, and story all agree.','good');complete(2,['units','equivalence','calculation','explanation'])}else feedback('Use the calculated fraction and attach the story unit.','try')})}
function renderRepair(){const t=track(),p=t.repair,x=state.sessions[sessionId]||{stage:0};if(!x.stage){$('#activity').innerHTML=`<p class="eyebrow">DIAGNOSE THE RULE</p><h3>A student writes: “${p.claim}.”</h3><p class="prompt">What is the exact error?</p><div class="answer-grid">${options([p.error,...p.wrongErrors],0,(t.pos+2)%3,'error')}</div>${controls()}${hint('Ask what the denominator names. Does the student still count one kind of part?')}`;$$('[data-error]').forEach(b=>b.onclick=()=>{const ok=b.dataset.error==='correct';tried(ok);if(ok){session(1);renderMission()}else feedback('Name how the fraction unit was changed or ignored.','try')});return}if(x.stage===1){$('#activity').innerHTML=`<p class="eyebrow">REPAIR THE CALCULATION</p><h3>Which work uses a valid common unit?</h3><div class="answer-grid">${options([p.correction,...p.wrongCorrections],0,t.pos,'correction')}</div>${controls()}${hint('Rename each fraction with equal-sized parts before adding or subtracting.')}`;$$('[data-correction]').forEach(b=>b.onclick=()=>{const ok=b.dataset.correction==='correct';tried(ok);if(ok){session(2);renderMission()}else feedback('Check that each renamed fraction keeps its original value.','try')});return}$('#activity').innerHTML=`<p class="eyebrow">CHECK REASONABLENESS</p><div class="repair-card"><span>Repaired work</span><strong>${p.correction}</strong></div><h3>Which statement checks the result?</h3><div class="answer-grid">${options([p.check,...p.wrongChecks],0,(t.pos+1)%3,'check')}</div>${controls()}${hint('Compare the result with zero, one whole, and the original fractions.')}`;$$('[data-check]').forEach(b=>b.onclick=()=>{const ok=b.dataset.check==='correct';tried(ok);if(ok){feedback('Repaired and checked. The unit and the size both make sense.','good');complete(3,['units','equivalence','calculation','explanation'],true)}else feedback('A good check uses the expected size of the result.','try')})}
function renderFresh(){const due=state.retestDue||Date.now()+72000000,ready=Date.now()>=due,previewDone=state.missions[FRACTIONOPS_CHAIN.missions[4].id]?.preview;if(!ready&&previewDone){$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">FAMILY PREVIEW COMPLETE</p><h3>Your method kept one shared fraction unit.</h3><p>This preview did not count as fresh evidence. Return after the wait for a new calculation.</p><a class="primary" href="./">Return home</a></div>`;return}if(!ready&&!state.previewFresh){$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Return after the method has faded.</strong><p>A new fraction operation checks whether the shared-unit idea stayed with you.</p><button class="secondary" data-action="preview">Preview for family review</button></div>`;return}const mode=ready?'challenge':'preview',sid=`fractionops-transfer:${mode}`;if(sessionId!==sid)load(sid);const t=track(),p=t.fresh[mode],x=state.sessions[sessionId]||{stage:0};if(!x.stage){$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · NEW FRACTIONS':'FAMILY PREVIEW · NO DELAYED EVIDENCE'}</p><h3>Calculate ${p.prompt}.</h3><p class="prompt">Which strategy keeps the fraction units meaningful?</p><div class="answer-grid">${options([p.strategy,'Add or subtract both numerators and denominators.','Choose the larger denominator and leave both numerators unchanged.'],0,p.pos,'freshstrategy')}</div>${controls()}${hint('First name a unit both fractions can use. Then operate on the counts.')}`;$$('[data-freshstrategy]').forEach(b=>b.onclick=()=>{const ok=b.dataset.freshstrategy==='correct';tried(ok);if(ok){session(1);renderMission()}else feedback('Choose a strategy that counts one kind of equal-sized part.','try')});return}$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED RESULT':'PREVIEW RESULT'}</p><div class="strategy-card"><strong>${p.strategy}</strong></div><h3>What result is proved?</h3><div class="answer-grid">${options([p.answer,'The numerator and denominator should both be added or subtracted.','The expression cannot be calculated.'],0,p.answerPos,'freshanswer')}</div>${controls()}${hint('Read the final equivalent-fraction calculation in the strategy.')}`;$$('[data-freshanswer]').forEach(b=>b.onclick=()=>{const ok=b.dataset.freshanswer==='correct';tried(ok);if(ok){const independent=attempts===0&&hints===0;feedback(ready?(independent?'Fresh transfer shown. You used common units independently.':'Fresh practice complete. Help was used, so this is saved as learning evidence.'):'Preview complete. Return later for fresh evidence.','good');complete(4,ready?['units','equivalence','calculation','explanation','transfer']:[],false,!ready)}else feedback('Match the result to the shared-unit work.','try')})}
function renderComplete(i){const m=FRACTIONOPS_CHAIN.missions[i];$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${m.title}</h3><p>Your work is saved for ${learner==='a'?'Ella':'Mila'}.</p>${i<4?'<button class="primary" data-action="next">Continue →</button>':'<a class="primary" href="./">Return home</a>'}</div>`}
function renderMission(){const i=state.activeMission,m=FRACTIONOPS_CHAIN.missions[i];if(i!==4&&sessionId!==m.id)load(m.id);$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;feedback('');if(done(i))renderComplete(i);else if(i===0)renderDiagnostic();else if(i===1)renderUnits();else if(i===2)renderStory();else if(i===3)renderRepair();else renderFresh()}
function renderNav(){$('#missionNav').innerHTML=FRACTIONOPS_CHAIN.missions.map((m,i)=>`<button class="mission-button ${i===state.activeMission?'active':''}" data-mission="${i}" ${unlocked(i)?'':'disabled'}><span class="mission-number">${m.number}</span><span class="mission-label">${m.title}</span><span class="mission-state">${done(i)?'✓':unlocked(i)?'›':'◌'}</span></button>`).join('');$$('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=+b.dataset.mission;sessionId=null;save();render()})}function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Learning depth">${Object.values(FRACTIONOPS_TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts this review path.</small>`;$('#trackSelect').onchange=e=>{state={...createBlankFractionOpsLearner(),track:e.target.value,family:state.family};sessionId=null;save();render()}}function renderEvidence(){const labels={units:'Fraction-unit reasoning',equivalence:'Equivalent renaming',calculation:'Exact calculation',explanation:'Reasonableness explanation',transfer:'Fresh transfer'};$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,v])=>`<div><span>${v}</span><strong class="${state.evidence[k]}">${state.evidence[k]}</strong></div>`).join('');$('#evidenceTitle').textContent=`${learner==='a'?'Ella':'Mila'}’s learning evidence`}
function wire(){const a=x=>$(`[data-action="${x}"]`);if(a('start'))a('start').onclick=()=>complete(0);if(a('next'))a('next').onclick=()=>{state.activeMission++;save();render()};if(a('hint'))a('hint').onclick=()=>{hints++;session(state.sessions[sessionId]?.stage||0);renderMission()};if(a('preview'))a('preview').onclick=()=>{state.previewFresh=true;save();render()}}function render(){completing=false;ensure();renderNav();renderTrack();renderEvidence();renderMission();wire();$('#helpNote').value=state.family.help||'';$('#explainNote').value=state.family.explain||'';$('#continueNote').value=state.family.continue||''}
$('#learnerSelect').value=learner;$('#learnerSelect').onchange=e=>{learner=e.target.value;store=read();store.learner=learner;state=store[learner]||createBlankFractionOpsLearner();sessionId=null;save();render()};['helpNote','explainNote','continueNote'].forEach(id=>$('#'+id).onchange=e=>{state.family[id==='helpNote'?'help':id==='explainNote'?'explain':'continue']=e.target.value;save()});$('#resetPath').onclick=()=>{if(confirm('Reset this learner’s fraction operation path?')){state=createBlankFractionOpsLearner();sessionId=null;save();render()}};render();
